CREATE OR REPLACE FUNCTION public.record_blog_view_v149(p_slug text, p_language text, p_visitor_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
declare today date:=(statement_timestamp() at time zone 'Asia/Seoul')::date; stamp timestamptz:=statement_timestamp(); fingerprint text; last_seen timestamptz;
begin
 if p_slug is null or length(p_slug)>160 or p_language not in ('ko','en','ja','zh','es','fr','vi','de','ru','id','pt','hi','tr','th','ar','bn') or p_visitor_id is null or length(p_visitor_id) not between 1 and 200 then raise exception 'Invalid view';end if;
 if not exists(select 1 from public.blog_posts where slug=p_slug and language=p_language) then return;end if;
 -- Preserve the existing public cumulative counter and its authorization/validation.
 perform public.record_blog_view(p_slug=>p_slug,p_language=>p_language,p_visitor_id=>p_visitor_id);
 fingerprint:=md5(today::text||':'||p_visitor_id);
 perform pg_advisory_xact_lock(hashtextextended('blog-daily:'||p_language||':'||p_slug||':'||fingerprint,149));
 select last_counted_at into last_seen from public.blog_view_dedup_v149 where day_kst=today and language=p_language and slug=p_slug and visitor_hash=fingerprint;
 if last_seen is not null and last_seen>stamp-interval '30 minutes' then return;end if;
 insert into public.blog_view_dedup_v149 values(today,p_language,p_slug,fingerprint,stamp) on conflict(day_kst,language,slug,visitor_hash) do update set last_counted_at=excluded.last_counted_at;
 insert into public.blog_daily_counts_v149 values(today,p_language,p_slug,1) on conflict(day_kst,language,slug) do update set views=public.blog_daily_counts_v149.views+1;
 -- Retain no raw visitor ID; expire deduplication records after the KST day changes.
 delete from public.blog_view_dedup_v149 where day_kst<today;
end $function$

CREATE OR REPLACE FUNCTION public.save_community_rich_post(p_id uuid, p_board text, p_title text, p_body text, p_html text, p_language text, p_category text, p_language_only boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare saved_id uuid;existing_board text;publisher boolean:=coalesce(public.can_publish_site_content(),false);
begin
 if auth.uid() is null then raise exception 'POST_PERMISSION';end if;
 if p_board is null or p_board not in ('community','notices') or p_language is null or p_language not in ('ko','en','ja','zh','es','fr','vi','de','ru','id','pt','hi','tr','th','ar','bn') or p_category is null or p_category not in ('general','worldcup','quiz','tier-list','random-pick') then raise exception 'POST_INVALID';end if;
 if p_id is null then
  if p_board='notices' and not publisher then raise exception 'POST_PERMISSION';end if;
  insert into public.community_posts(board,title,body,body_html,language,category,language_only,author_id)
   values(p_board,p_title,p_body,p_html,p_language,case when p_board='notices' then 'general' else p_category end,case when p_board='community' then coalesce(p_language_only,false) else false end,auth.uid()) returning id into saved_id;
 else
  select board into existing_board from public.community_posts where id=p_id for update;
  if not found then raise exception 'POST_NOT_FOUND';end if;
  if existing_board<>p_board then raise exception 'POST_INVALID';end if;
  perform public.update_community_post(p_id,p_title,p_body,p_language,p_category,p_language_only);
  update public.community_posts set body_html=p_html where id=p_id; saved_id:=p_id;
 end if;
 return saved_id;
end $function$

CREATE OR REPLACE FUNCTION public.save_guest_quiz(p_quiz_id uuid, p_guest_nickname text, p_password text, p_quiz jsonb, p_questions jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_id uuid := coalesce(p_quiz_id, gen_random_uuid());
  v_q jsonb;
  v_record public.quizzes%rowtype;
  v_rows jsonb;
  v_sources jsonb;
  v_languages jsonb;
  v_image text;
  v_count integer;
  allowed constant text[] := array['en','ko','ja','zh','es','fr','vi','de','ru','id','pt','hi','tr','th','ar','bn'];
begin
  if length(btrim(coalesce(p_guest_nickname,''))) not between 1 and 20 or p_password is null
    or length(p_password) not between 4 and 50 or octet_length(p_password) > 72 then
    return jsonb_build_object('error','GUEST_CREDENTIALS_INVALID');
  end if;
  if p_quiz_id is not null and not public._check_guest_quiz_password(p_quiz_id, p_guest_nickname, p_password) then
    return jsonb_build_object('error','GUEST_AUTH_FAILED');
  end if;
  if jsonb_typeof(p_quiz) is distinct from 'object' or jsonb_typeof(p_questions) is distinct from 'array' then
    raise exception 'Invalid quiz data';
  end if;
  v_count := jsonb_array_length(p_questions);
  if v_count not between 1 and 500 or length(btrim(coalesce(p_quiz->>'title',''))) not between 1 and 100
    or length(coalesce(p_quiz->>'description','')) > 500 or octet_length(p_quiz::text) > 262144
    or octet_length(p_questions::text) > 2097152 then raise exception 'Invalid quiz size'; end if;
  if not coalesce(p_quiz->>'original_language','') = any(allowed) then raise exception 'Invalid quiz language'; end if;
  if not coalesce(p_quiz->>'category','') = any(array['game','entertainment','animation','food','sports','knowledge','other']) then
    raise exception 'Invalid quiz category'; end if;
  if not coalesce(p_quiz->>'answer_reveal_mode','both') = any(array['both','immediate','final','none']) then
    raise exception 'Invalid answer reveal mode'; end if;
  if jsonb_typeof(p_quiz->'content_languages') is distinct from 'array' then raise exception 'Invalid content languages'; end if;
  select jsonb_agg(distinct code) into v_languages from (
    select jsonb_array_elements_text(p_quiz->'content_languages') as code union select p_quiz->>'original_language'
  ) languages where code = any(allowed);

  for v_q in select value from jsonb_array_elements(p_questions) loop
    if jsonb_typeof(v_q) is distinct from 'object' or length(btrim(coalesce(v_q->>'question_text',''))) = 0
      or not coalesce(v_q->>'question_type','') = any(array['multiple_choice','short_answer']) then
      raise exception 'Invalid question'; end if;
    if v_q->>'question_type' = 'multiple_choice' then
      if jsonb_typeof(v_q->'options') is distinct from 'array' then raise exception 'Invalid options'; end if;
      if jsonb_array_length(v_q->'options') < 2 or coalesce((v_q->>'correct_index')::integer,-1) < 0
        or (v_q->>'correct_index')::integer >= jsonb_array_length(v_q->'options') then raise exception 'Invalid correct answer'; end if;
    else
      if jsonb_typeof(v_q->'answers') is distinct from 'array' then raise exception 'Invalid answers'; end if;
      if jsonb_array_length(v_q->'answers') = 0 then raise exception 'Missing answer'; end if;
    end if;
    v_image := coalesce(v_q->>'image_url','');
    -- Bind each image to its public source World Cup, including converted YouTube previews.
    if auth.uid() is null and not exists (
      select 1 from public.worldcups w cross join lateral jsonb_array_elements(coalesce(w.data::jsonb,'[]'::jsonb)) c
      where w.id = (v_q->>'source_worldcup_id')::uuid and w.deleted_at is null
      and (coalesce(c->>'image','') = v_image or
        'https://img.youtube.com/vi/' || substring(c->>'image' from '(?i)(?:youtu.be/|youtube.com/(?:embed/|shorts/|live/|watch\?(?:.*&)?v=))([A-Za-z0-9_-]{11})') || '/mqdefault.jpg' = v_image)
    ) and not exists (
      -- A previously approved image remains editable after its author signs out.
      -- This also preserves imported images if the source World Cup is later removed.
      select 1 from public.quiz_questions saved
      where p_quiz_id is not null and saved.quiz_id = p_quiz_id
        and coalesce(saved.image_url,'') = v_image
        and coalesce(saved.source_worldcup_id::text,'') = coalesce(v_q->>'source_worldcup_id','')
    ) then return jsonb_build_object('error','GUEST_SOURCE_REQUIRED'); end if;
  end loop;
  if auth.uid() is null and nullif(p_quiz->>'thumbnail_url','') is not null and not exists(
    select 1 from jsonb_array_elements(p_questions) q where q->>'image_url' = p_quiz->>'thumbnail_url'
  ) and not exists (
    select 1 from public.quizzes saved where p_quiz_id is not null and saved.id = p_quiz_id
      and saved.thumbnail_url = p_quiz->>'thumbnail_url'
  ) then return jsonb_build_object('error','GUEST_SOURCE_REQUIRED'); end if;
  select coalesce(jsonb_agg(distinct value->>'source_worldcup_id') filter (where value->>'source_worldcup_id' is not null),'[]'::jsonb) into v_sources from jsonb_array_elements(p_questions);
  select jsonb_agg(value || jsonb_build_object('quiz_id',v_id,'sort_order',ordinality-1)) into v_rows
    from jsonb_array_elements(p_questions) with ordinality;
  -- Populate using the existing table types (JSON arrays and PostgreSQL arrays are both supported).
  v_record := jsonb_populate_record(null::public.quizzes, p_quiz || jsonb_build_object(
    'user_id',null,'guest_nickname',btrim(p_guest_nickname),'source_worldcup_ids',v_sources,
    'question_count',v_count,'is_published',true,'content_languages',v_languages));
  if p_quiz_id is null then
    insert into public.quizzes(id,user_id,guest_nickname,title,title_translations,description,description_translations,
      category,thumbnail_url,question_count,original_language,content_languages,answer_reveal_mode,source_worldcup_ids,is_published)
    values(v_id,null,v_record.guest_nickname,btrim(v_record.title),v_record.title_translations,coalesce(v_record.description,''),
      v_record.description_translations,v_record.category,v_record.thumbnail_url,v_count,v_record.original_language,
      v_record.content_languages,v_record.answer_reveal_mode,v_record.source_worldcup_ids,true);
    insert into public.quiz_guest_auth(quiz_id,nickname,password_hash) values(v_id,btrim(p_guest_nickname),crypt(p_password,gen_salt('bf',10)));
  else
    update public.quizzes set title = btrim(v_record.title), title_translations = v_record.title_translations,
      description = coalesce(v_record.description,''),description_translations = v_record.description_translations,
      category = v_record.category,thumbnail_url = v_record.thumbnail_url,question_count = v_count,
      content_languages = v_record.content_languages,answer_reveal_mode = v_record.answer_reveal_mode,
      source_worldcup_ids = v_record.source_worldcup_ids where id = v_id and user_id is null;
    -- Original language, creation date, author and statistics remain unchanged when editing.
    delete from public.quiz_questions where quiz_id = v_id;
  end if;
  insert into public.quiz_questions(quiz_id,question_type,question_text,question_translations,image_url,options,options_translations,
    correct_index,answers,answer_match_options,explanation,explanation_translations,source_worldcup_id,source_candidate_id,auto_choices,sort_order)
  select quiz_id,question_type,question_text,question_translations,image_url,options,options_translations,correct_index,answers,
    answer_match_options,explanation,explanation_translations,source_worldcup_id,source_candidate_id,auto_choices,sort_order
    from jsonb_populate_recordset(null::public.quiz_questions,v_rows);
  return jsonb_build_object('id',v_id);
end $function$

CREATE OR REPLACE FUNCTION public.save_site_blog(p_language text, p_slug text, p_title text, p_description text, p_content text, p_allow_update boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
if not public.can_publish_site_content() then raise exception 'Administrator access required'; end if;
if p_language not in ('ko','en','ja','zh','es','fr','vi','de','ru','id','pt','hi','tr','th','ar','bn') or p_slug !~ '^[a-z0-9][a-z0-9_-]{0,159}$' or length(btrim(p_title)) not between 1 and 200 or length(p_description)>1000 or length(p_content)>200000 then raise exception 'Invalid article'; end if;
perform pg_advisory_xact_lock(hashtext('site-blog:'||p_language||':'||p_slug));
if exists(select 1 from public.blog_posts where language=p_language and slug=p_slug) then
 if not p_allow_update then raise exception 'This URL already exists. Open the existing article and use Edit.'; end if;
 update public.blog_posts set title=btrim(p_title),description=p_description,content=p_content where language=p_language and slug=p_slug;
else
 insert into public.blog_posts(language,slug,title,description,content) values(p_language,p_slug,btrim(p_title),p_description,p_content);
end if;
end $function$

CREATE OR REPLACE FUNCTION public.update_community_post(p_id uuid, p_title text, p_body text, p_language text, p_category text, p_language_only boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare target public.community_posts%rowtype;publisher boolean:=coalesce(public.can_publish_site_content(),false);
begin
 if auth.uid() is null then raise exception 'POST_PERMISSION';end if;
 select * into target from public.community_posts where id=p_id for update;
 if not found then raise exception 'POST_NOT_FOUND';end if;
 if not publisher and (target.author_id<>auth.uid() or target.board<>'community') then raise exception 'POST_PERMISSION';end if;
 if p_language is null or p_language not in ('ko','en','ja','zh','es','fr','vi','de','ru','id','pt','hi','tr','th','ar','bn') or p_category is null or p_category not in ('general','worldcup','quiz','tier-list','random-pick') then raise exception 'POST_INVALID';end if;
 update public.community_posts set title=p_title,body=p_body,body_html=null,language=p_language,category=case when target.board='notices' then 'general' else p_category end,language_only=case when target.board='community' then coalesce(p_language_only,false) else false end where id=p_id;
end $function$
